sparql_content:
#+ endpoint: https://graphdb.dumontierlab.com/repositories/shapes-registry
#+ endpoint_in_url: False
#+ summary:  List all active SPARQL endpoints
#+ description: List all active SPARQL endpoints retrieved from SPARQL query file parsing and the number of associated SPARQL queries
#+ tags:
#+   - Get resources
#+ method: GET
# pagination: 100

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema: <https://schema.org/>
PREFIX void: <http://rdfs.org/ns/void#>
PREFIX void-ext: <http://ldf.fi/void-ext#>
SELECT DISTINCT ?sparql_endpoint (count(distinct ?datasets_graph) AS ?datasets_graph_count) (count(distinct ?query_file) AS ?queries_count)
WHERE { 
  ?sparql_endpoint a schema:EntryPoint .
  OPTIONAL {
    ?query_file void:sparqlEndpoint ?sparql_endpoint ;
      schema:query ?query
  }
  OPTIONAL {
    GRAPH ?sparql_endpoint {
      ?datasets_graph a void:Dataset .
      FILTER EXISTS { ?datasets_graph void:propertyPartition ?propertyPartition . }
    } 
  }
} GROUP BY ?sparql_endpoint ORDER BY DESC(?queries_count) DESC(?datasets_graph_count)

#+ summary: Natural products structurally similar to chemicals
#+ description: How many compounds are structurally similar to eugenol and eugenyl acetate? Results are grouped by the parent taxon of the organism they were found in.
#+ endpoint: https://query.wikidata.org/bigdata/namespace/wdq/sparql
#+ pagination: 100
#+ method: GET
#+ tags:
#+   - Natural products
#+   - Structural similarity

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX hint: <http://www.bigdata.com/queryHints#>
#title:How many compounds are structurally similar to eugenol and eugenyl acetate? Results are grouped by the parent taxon of the organism they were found in.
PREFIX sachem: <http://bioinfo.uochb.cas.cz/rdf/v1.0/sachem#>
# prefixes needed for structural similarity search
PREFIX idsm: <https://idsm.elixir-czech.cz/sparql/endpoint/>
SELECT ?parent_taxon ?parent_taxon_name (COUNT(DISTINCT ?compound) AS ?count) WHERE {
    SERVICE idsm:wikidata {
        VALUES ?CUTOFF {
            "0.85"^^xsd:double
        }
        SERVICE <https://query.wikidata.org/bigdata/namespace/wdq/sparql> {
            VALUES ?derivatives {
                wd:Q423357
                wd:Q27116129
            }
            ?derivatives wdt:P233 ?smiles.
        }
        ?compound sachem:similarCompoundSearch [
        sachem:query ?smiles;
        sachem:cutoff ?CUTOFF
        ].
    } hint:Prior hint:runFirst TRUE.
    ?compound wdt:P703/wdt:P171 ?parent_taxon.
    ?parent_taxon wdt:P225 ?parent_taxon_name.
}
GROUP BY ?parent_taxon ?parent_taxon_name
ORDER BY DESC (?count)

#+ summary: Full-text search for Semantic Interoperability Profiles
#+ endpoint: https://query.np.trustyuri.net/repo/text
#+ method: GET

prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#>
prefix np: <http://www.nanopub.org/nschema#>
prefix npa: <http://purl.org/nanopub/admin/>
prefix npx: <http://purl.org/nanopub/x/>
prefix xsd: <http://www.w3.org/2001/XMLSchema#>
prefix dct: <http://purl.org/dc/terms/>
prefix fip: <https://w3id.org/fair/fip/terms/>
prefix search: <http://www.openrdf.org/contrib/lucenesail#>

select distinct ?np ?label ?description ?community ?date ?qualifier (max(?score) as ?maxscore) where {
  graph npa:graph {
    <https://w3id.org/np/RA27Uhopq4MHZziL2lKXX-wTb1jz4KVLbHaupxyAcCt9Y> npa:hasValidSignatureForPublicKey ?curators_np_pk .
    ?latest_curators_np npa:hasValidSignatureForPublicKey ?curators_np_pk .
    filter not exists { ?latest_curators_npx npx:invalidates ?latest_curators_np ; npa:hasValidSignatureForPublicKey ?curators_np_pk . }
    ?latest_curators_np np:hasAssertion ?latest_curators_assertion .
  }
  graph npa:networkGraph {
    ?latest_curators_np (npx:supersedes)* <https://w3id.org/np/RA27Uhopq4MHZziL2lKXX-wTb1jz4KVLbHaupxyAcCt9Y> .
    filter not exists { ?latest_curators_npxx npx:supersedes ?latest_curators_np }
  }

  graph npa:graph {
    ?np rdfs:label ?label ;
        npa:hasValidSignatureForPublicKey ?pubkey ;
        dct:created ?date .
    filter exists { ?np npx:hasNanopubType fip:Semantic-Interoperability-Profile . }
    filter not exists { ?np npx:hasNanopubType npx:ExampleNanopub . }
    filter not exists { ?npx npx:invalidates ?np ; npa:hasValidSignatureForPublicKey ?pubkey . }
  }
  optional { service <https://query.np.trustyuri.net/repo/full> {
    graph npa:graph {
      ?np np:hasAssertion ?a .
      ?np np:hasPublicationInfo ?i .
    }
    graph ?a {
      ?fip dct:description ?description .
      ?fip fip:declared-by ?community .

    }
    graph ?i {
      ?np npx:introduces ?fip .
    }
  } }
  ?np search:matches [
    search:query ?_query ;
    search:property ?property ;
    search:score ?score ;
    search:snippet ?snippet ] .
  optional { service <https://query.np.trustyuri.net/repo/type/cd51a3ac3e109fd12aacd5a324e14ebff644ce209c916e4250a3f50c2ddf0051> {  # (http://purl.org/nanopub/x/qualifies)
    graph npa:graph {
      ?qualification_np np:hasAssertion ?qa ;
        npa:hasValidSignatureForPublicKey ?qpubkey .
      filter not exists { ?qualification_npx npx:invalidates ?qualification_np ; npa:hasValidSignatureForPublicKey ?qpubkey . }
    }
    graph ?latest_curators_assertion {
      ?qpubkeys npx:hasPublicKey ?qpubkey .
    }
    graph ?qa {
      ?qualifier npx:qualifies ?np .
    }
  } }
  filter not exists { service <https://query.np.trustyuri.net/repo/type/39692876d0a7881c82e9a2cb6dc8859fb16fa69fb41cea2ace2f8fa70bc52aed> {  # (http://purl.org/nanopub/x/disapprovesOf)
    graph npa:graph {
      ?disapproval_np np:hasAssertion ?da ;
        npa:hasValidSignatureForPublicKey ?dpubkey .
      filter not exists { ?disapproval_npx npx:invalidates ?disapproval_np ; npa:hasValidSignatureForPublicKey ?dpubkey . }
    }
    graph ?latest_curators_assertion {
      ?qpubkeys npx:hasPublicKey ?dpubkey .
    }
    graph ?da {
      ?disapprover npx:disapprovesOf ?np .
    }
  } }
}
group by ?np ?description ?label ?community ?date ?qualifier
order by desc(?maxscore)

#+ summary: "Access to all SensorThings resources begins at the base resource path"
#+ description: "Navigating to the base resource path will return a JSON array of the available SensorThings resource endpoints. NOTE: make sure response content type is application/json"
#+ endpoint: "https://rohub2020-api-virtuoso-route-rohub.apps.paas-dev.psnc.pl/sparql"
#+ method: GET
#+ endpoint_in_url: False
#+ transform: {
#+   "description": "?info",
#+   "$anchor": "description",
#+   "value": {
#+     "name": "?name",
#+     "url": "?url",
#+   }
#+ }

PREFIX iliad-api: <https://w3id.org/iliad/jf/api/>

SELECT DISTINCT ?info ?name ?url
WHERE {
     VALUES (?info ?name ?url) {
     ("OGC SensorThings API base resource path" "Things" <https://w3id.org/iliad/jf/api/v1.0/Things>)
     ("OGC SensorThings API base resource path" "Locations" <https://w3id.org/iliad/jf/api/v1.0/Locations>)
     ("OGC SensorThings API base resource path" "HistoricalLocations" <https://w3id.org/iliad/jf/api/v1.0/HistoricalLocations>)
     ("OGC SensorThings API base resource path" "Datastreams" <https://w3id.org/iliad/jf/api/v1.0/Datastreams>)
     ("OGC SensorThings API base resource path" "Sensors" <https://w3id.org/iliad/jf/api/v1.0/Sensors>)
     ("OGC SensorThings API base resource path" "Observations" <https://w3id.org/iliad/jf/api/v1.0/Observations>)
     ("OGC SensorThings API base resource path" "ObservedProperties" <https://w3id.org/iliad/jf/api/v1.0/ObservedProperties>)
     ("OGC SensorThings API base resource path" "FeaturesOfInterest" <https://w3id.org/iliad/jf/api/v1.0/FeaturesOfInterest>)}
}

#+ summary: Adresses Golden Agents with streetnames starting with 'zee'
#+ description: Example query for testing the HuC Geo Plugin for Yasgui. Also usable for the grlc test
#+ pagination: 100
#+ tags:
#+  - Geo
#+  - Golden Agents
#+ endpoint: https://data.create.humanities.uva.nl/sparql

PREFIX hg: <http://rdf.histograph.io/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX schema: <https://schema.org/>
PREFIX roar: <https://w3id.org/roar#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT * WHERE {
   ?address a roar:LocationObservation ;
       rdfs:label ?wktTooltip ;
       hg:liesIn ?street .

   ?street a hg:Street ;
       rdfs:label ?streetLabel ;
       geo:hasGeometry/geo:asWKT ?streetWKT .

   ?point a geo:Geometry ;
       schema:geoWithin ?address ;
       geo:asWKT ?wkt .

  FILTER(REGEX(?streetLabel, 'zee', 'i'))

}

#+ summary: Count the number of features annotated as aspidosperma type alkaloids by CANOPUS (p>0.5) in the different samples
#+ description: Count the number of features annotated as aspidosperma type alkaloids by CANOPUS (p>0.5) in the different samples
#+ endpoint: https://enpkg.commons-lab.org/graphdb/repositories/ENPKG
#+ tags:
#+   - ENPKG


PREFIX enpkg: <https://enpkg.commons-lab.org/kg/>
PREFIX enpkgmodule: <https://enpkg.commons-lab.org/module/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wd: <http://www.wikidata.org/entity/>

SELECT ?extract ?organe ?species_name ?genus_name ?family_name ?count_of_selected_class
WHERE
    {  
    ?material enpkg:has_lab_process ?extract .
        ?material enpkgmodule:has_organe ?organe .
        ?material enpkg:has_wd_id ?wd_sp .
        OPTIONAL
        {
            SERVICE <https://query.wikidata.org/sparql> {
            ?wd_sp wdt:P225 ?species_name .
            ?family wdt:P31 wd:Q16521 ;
                wdt:P105 wd:Q35409 ;
                wdt:P225 ?family_name ;
                ^wdt:P171* ?wd_sp .
            ?genus wdt:P31 wd:Q16521 ;
                wdt:P105 wd:Q34740 ;
                wdt:P225 ?genus_name ;
                ^wdt:P171* ?wd_sp 
            }
        }
        {
            SELECT ?extract (COUNT(DISTINCT ?feature) AS ?count_of_selected_class)
            WHERE
            {   
                ?extract rdf:type enpkg:LabExtract .
                    ?extract enpkg:has_LCMS ?lcms .
                        ?lcms rdf:type enpkg:LCMSAnalysisPos .
                        ?lcms enpkg:has_lcms_feature_list ?feature_list .
                            ?feature_list enpkg:has_lcms_feature ?feature .
                                ?feature enpkg:has_canopus_annotation ?canopus .
                                    ?canopus enpkg:has_canopus_npc_class ?np_class .
                                    ?canopus enpkg:has_canopus_npc_class_prob ?class_prob .
                                    FILTER(regex(str(?np_class), "Aspidosperma_type")) .
                                    FILTER((?class_prob > 0.5)) .
            } GROUP BY ?extract ORDER BY DESC(?count_of_selected_class)
        }
    }

#+ summary: A query for the Biocuration organizing committee and scientific program committee
#+ endpoint: https://query.wikidata.org/sparql
#+ tags:
#+   - conference
#+   - bibliometrics
#defaultView:Table

SELECT 
  ?person ?personLabel ?personDescription ?genderLabel ?image
  ?nationalityLabel ?orcid ?linkedin ?twitter ?gscholar ?github
  (GROUP_CONCAT(DISTINCT ?topic_label; separator=", ") AS ?topics)
  (MAX(?start_date) as ?max_start_date)
  (SAMPLE(?employerLabel) as ?employerLabel_)
WHERE 
{
  wd:Q111430238 wdt:P664|wdt:P5804 ?person .
  ?person wdt:P496 ?orcid .
  OPTIONAL { ?person wdt:P18 ?image . }
  OPTIONAL { ?person wdt:P21 ?gender . }
  OPTIONAL { ?person wdt:P2002 ?twitter . }
  OPTIONAL { ?person wdt:P27 ?nationality . }
  OPTIONAL { ?person wdt:P6634 ?linkedin . }
  OPTIONAL { ?person wdt:P1960 ?gscholar . }
  OPTIONAL { ?person wdt:P2037 ?github . }
  OPTIONAL { ?person wdt:P101 ?topic . ?topic rdfs:label ?topic_label . FILTER (LANG(?topic_label) = 'en') }
  OPTIONAL { 
    ?person p:P108 ?statement .
    ?statement ps:P108 ?employer .
    ?employer rdfs:label ?employerLabel
    filter(lang(?employerLabel) = "en")
    OPTIONAL { 
      ?statement pq:P580 ?start_date . 
    }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". } # Helps get the label in your language, if not, then en language
}
GROUP BY
  ?person ?personLabel ?personDescription ?genderLabel ?image
  ?nationalityLabel ?orcid ?linkedin ?twitter ?gscholar ?github
ORDER BY ?personLabel

